mapper.select:
SELECT mr.MedicalID as medicalId, mr.PetID as petId, p.PetName as petName, p.Breed as breed, u.UserID as userId, u.UserName as userName, a.ApptID as apptId, mr.MedicalTime as medicalTime, mr.MedicalFee as medicalFee, mr.Diagnosis as diagnosis, mr.StoreID as storeId, s.StoreName as storeName FROM medicalRecord mr LEFT JOIN pet p ON mr.PetID = p.PetID LEFT JOIN user u ON p.UserID = u.UserID LEFT JOIN store s ON mr.StoreID = s.StoreID LEFT JOIN apptMedical am ON mr.MedicalID = am.MedicalID LEFT JOIN appointment a ON am.ApptID = a.ApptID WHERE 1=1
AND p.PetName LIKE CONCAT('%', #{dto.petName}, '%')
AND mr.MedicalTime >= #{dto.startTime}
AND mr.MedicalTime <= #{dto.endTime}
ORDER BY mr.MedicalID ASC

SELECT mr.MedicalID as medicalId, mr.PetID as petId, p.PetName as petName, p.Breed as breed, mr.MedicalTime as medicalTime, mr.MedicalFee as medicalFee, mr.Diagnosis as diagnosis FROM medicalRecord mr LEFT JOIN pet p ON mr.PetID = p.PetID WHERE p.UserID = #{dto.userId}
AND mr.PetID = #{dto.petId}
ORDER BY mr.MedicalTime DESC
